[CmdletBinding()]
param([switch]$Detailed)

$ErrorActionPreference='Stop'
$projectRoot=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..'))
$checks=New-Object System.Collections.Generic.List[object]
$failed=$false
$tempRoot=Join-Path $env:TEMP ('marketing-os-tests-'+[guid]::NewGuid().ToString('N'))
[IO.Directory]::CreateDirectory($tempRoot)|Out-Null

function Add-Check{param([string]$Name,[bool]$Passed,[string]$Detail);$script:checks.Add([pscustomobject][ordered]@{name=$Name;passed=$Passed;detail=$Detail});if(-not$Passed){$script:failed=$true}}
function Invoke-Script{
    param([string]$ScriptPath,[string[]]$Arguments)
    $previousErrorPreference=$ErrorActionPreference
    try{
        $ErrorActionPreference='Continue'
        $output=& powershell.exe -NoProfile -ExecutionPolicy Bypass -File $ScriptPath @Arguments 2>&1
        $exitCode=$LASTEXITCODE
    }
    finally{$ErrorActionPreference=$previousErrorPreference}
    [pscustomobject]@{exitCode=$exitCode;output=($output-join[Environment]::NewLine)}
}
function Add-ExitCheck{param([string]$Name,$Result,[bool]$ShouldPass=$true);$pass=if($ShouldPass){$Result.exitCode-eq0}else{$Result.exitCode-ne0};$detail="exit={0}"-f$Result.exitCode;if(-not$pass-and-not[string]::IsNullOrWhiteSpace([string]$Result.output)){$detail+="; output={0}"-f([string]$Result.output)};Add-Check $Name $pass $detail}
function Write-Utf8Text{param([string]$Path,[string]$Text);$dir=Split-Path -Parent $Path;if(-not(Test-Path -LiteralPath $dir)){[IO.Directory]::CreateDirectory($dir)|Out-Null};[IO.File]::WriteAllText($Path,$Text,[Text.UTF8Encoding]::new($false))}
function Write-Utf8Json{param([string]$Path,$Object);Write-Utf8Text $Path (($Object|ConvertTo-Json -Depth 100)+[Environment]::NewLine)}
function Copy-JsonObject{param($Object);return (($Object|ConvertTo-Json -Depth 100)|ConvertFrom-Json)}
function Read-JsonOutput{param($Result);try{return ($Result.output|ConvertFrom-Json)}catch{return $null}}

$queuePath=Join-Path $projectRoot 'queue\work-items.json'
$registryPath=Join-Path $projectRoot 'registry\clients.json'
$controlPath=Join-Path $projectRoot 'CONTROL.md'
$fixturePath=Join-Path $projectRoot 'tests\fixtures\valid-worker-handoff.json'
$queue=Get-Content -LiteralPath $queuePath -Raw -Encoding UTF8|ConvertFrom-Json
$registry=Get-Content -LiteralPath $registryPath -Raw -Encoding UTF8|ConvertFrom-Json

try{
    $jsonPaths=@(
        'queue\work-items.json','registry\clients.json','registry\paid-media-roster.json',
        'workflows\marketing-chief.workflow.json','workflows\marketing-chief-execution-graph.workflow.json','workflows\communication-triggered-ad-launch.workflow.json','workflows\daily-paid-media-optimization.workflow.json',
        'schemas\worker-handoff.schema.json','schemas\marketing-execution-graph.schema.json','schemas\design-contract.schema.json','schemas\ad-launch-request.schema.json','schemas\ad-launch-authority.schema.json','schemas\ad-provider-packet.schema.json','schemas\ad-provider-readiness.schema.json','schemas\paid-media-client-config.schema.json','schemas\paid-media-launch-blueprint.schema.json','schemas\paid-media-roster.schema.json',
        'clients\replenish-7-eleven\paid-media\launch-authority.json','clients\replenish-7-eleven\paid-media\launch-config.json','clients\replenish-7-eleven\paid-media\blueprints\google_ads.json',
        'clients\fresh-blends-kwik-trip\paid-media\launch-authority.json','clients\fresh-blends-kwik-trip\paid-media\launch-config.json','clients\fresh-blends-kwik-trip\paid-media\blueprints\google_ads.json',
        'clients\kimberly-james-bridal\paid-media\launch-authority.json','clients\kimberly-james-bridal\paid-media\launch-config.json','clients\kimberly-james-bridal\paid-media\blueprints\google_ads.json','clients\kimberly-james-bridal\paid-media\blueprints\meta_ads.json',
        'clients\omega-landscaping\paid-media\launch-authority.json','clients\omega-landscaping\paid-media\launch-config.json','clients\omega-landscaping\paid-media\blueprints\google_ads.json',
        'clients\onsite-concrete-landscape\paid-media\launch-authority.json','clients\onsite-concrete-landscape\paid-media\launch-config.json','clients\onsite-concrete-landscape\paid-media\blueprints\google_ads.json',
        'clients\fagan-painting\paid-media\launch-authority.json','clients\fagan-painting\paid-media\launch-config.json','clients\fagan-painting\paid-media\blueprints\meta_ads.json',
        'clients\shadow-heating-cooling\paid-media\launch-authority.json','clients\shadow-heating-cooling\paid-media\launch-config.json','clients\shadow-heating-cooling\paid-media\blueprints\meta_ads.json',
        'intake\index.json','state\intake-sync.json','state\system-health.json','state\task-continuity.json','state\access-coverage.json','state\ad-provider-readiness.json'
    )
    foreach ($path in $jsonPaths){
        $full=Join-Path $projectRoot $path
