        $parseErrors=$null;[void][Management.Automation.Language.Parser]::ParseFile($script.FullName,[ref]$null,[ref]$parseErrors)
        Add-Check ("powershell-parse:{0}"-f$script.Name) (@($parseErrors).Count-eq0) ("errors={0}"-f@($parseErrors).Count)
    }
    foreach ($script in @(Get-ChildItem -LiteralPath (Join-Path $PSScriptRoot 'providers') -Filter '*.ps1' -File)){
        $parseErrors=$null;[void][Management.Automation.Language.Parser]::ParseFile($script.FullName,[ref]$null,[ref]$parseErrors)
        Add-Check ("powershell-parse:providers/{0}"-f$script.Name) (@($parseErrors).Count-eq0) ("errors={0}"-f@($parseErrors).Count)
    }

    Add-ExitCheck 'client-registry' (Invoke-Script (Join-Path $PSScriptRoot 'Test-ClientRegistry.ps1') @())
    Add-ExitCheck 'paid-media:daily-review-focused-suite' (Invoke-Script (Join-Path $projectRoot 'tests\Test-DailyPaidMediaReview.ps1') @())
    Add-ExitCheck 'execution-graph:focused-suite' (Invoke-Script (Join-Path $projectRoot 'tests\Test-MarketingExecutionGraph.ps1') @())
