    Add-ExitCheck 'queue:update-dry-run' (Invoke-Script (Join-Path $PSScriptRoot 'Update-MarketingQueue.ps1') @('-WorkItemId',$hope.id,'-ExpectedQueueRevision',[string]$queue.revision,'-ExpectedWorkItemVersion',[string]$hope.version,'-Priority',[string]$hope.priority.level,'-DryRun'))
    Add-ExitCheck 'queue:reject-pending-approval-bypass' (Invoke-Script (Join-Path $PSScriptRoot 'Update-MarketingQueue.ps1') @('-WorkItemId',$hope.id,'-ExpectedQueueRevision',[string]$queue.revision,'-ExpectedWorkItemVersion',[string]$hope.version,'-Status','in_progress','-DryRun')) $false
    $nkcdc=@($queue.workItems|Where-Object{$_.id-eq'wi-20260715-0003'})[0]
    Add-ExitCheck 'queue:reject-risky-automatic-text' (Invoke-Script (Join-Path $PSScriptRoot 'Update-MarketingQueue.ps1') @('-WorkItemId',$nkcdc.id,'-ExpectedQueueRevision',[string]$queue.revision,'-ExpectedWorkItemVersion',[string]$nkcdc.version,'-NextAction','Send the deck to the client.','-ActionClass','local_artifact','-DryRun')) $false

    $doneQueue=Copy-JsonObject $queue;$doneQueue.revision=301;$doneItem=@($doneQueue.workItems|Where-Object{$_.id-eq'wi-20260715-0003'})[0];$doneItem.version=20;$doneItem.status='verification';$doneItem.outcome=$null;$doneQueuePath=Join-Path $tempRoot 'queue\done.json';$doneControl=Join-Path $tempRoot 'queue\done-control.md';Write-Utf8Json $doneQueuePath $doneQueue
    Add-ExitCheck 'queue:reject-done-without-outcome' (Invoke-Script (Join-Path $PSScriptRoot 'Update-MarketingQueue.ps1') @('-QueuePath',$doneQueuePath,'-ControlPath',$doneControl,'-RegistryPath',$registryPath,'-WorkItemId',$doneItem.id,'-ExpectedQueueRevision','301','-ExpectedWorkItemVersion','20','-Status','done','-DryRun')) $false
    Add-ExitCheck 'queue:reject-empty-outcome' (Invoke-Script (Join-Path $PSScriptRoot 'Update-MarketingQueue.ps1') @('-QueuePath',$doneQueuePath,'-ControlPath',$doneControl,'-RegistryPath',$registryPath,'-WorkItemId',$doneItem.id,'-ExpectedQueueRevision','301','-ExpectedWorkItemVersion','20','-Status','done','-OutcomeSummary','   ','-DryRun')) $false
    $doneItem.outcome=[pscustomobject]@{status='ready';summary='Old unverified note.';verifiedAt='2026-07-16T05:00:00Z'};Write-Utf8Json $doneQueuePath $doneQueue
    Add-ExitCheck 'queue:reject-stale-unverified-outcome' (Invoke-Script (Join-Path $PSScriptRoot 'Update-MarketingQueue.ps1') @('-QueuePath',$doneQueuePath,'-ControlPath',$doneControl,'-RegistryPath',$registryPath,'-WorkItemId',$doneItem.id,'-ExpectedQueueRevision','301','-ExpectedWorkItemVersion','20','-Status','done','-DryRun')) $false

    $emergencyQueue=Copy-JsonObject $queue;$emergencyQueue.revision=401;$target=@($emergencyQueue.workItems|Where-Object{$_.id-eq'wi-20260715-0003'})[0];$target.version=30;$target.status='ready';$target.outcome=$null;$target.lane='emergency';$target.priority.level='P0';$target|Add-Member -NotePropertyName emergencyRationale -NotePropertyValue 'Time-critical local recovery test.' -Force
    $active=Copy-JsonObject $target;$active.id='wi-test-emergency-active';$active.version=1;$active.status='in_progress';$emergencyQueue.workItems=@($emergencyQueue.workItems)+$active;$emergencyQueuePath=Join-Path $tempRoot 'queue\emergency.json';$emergencyControl=Join-Path $tempRoot 'queue\emergency-control.md';Write-Utf8Json $emergencyQueuePath $emergencyQueue
    Add-ExitCheck 'wip:reject-second-emergency' (Invoke-Script (Join-Path $PSScriptRoot 'Update-MarketingQueue.ps1') @('-QueuePath',$emergencyQueuePath,'-ControlPath',$emergencyControl,'-RegistryPath',$registryPath,'-WorkItemId',$target.id,'-ExpectedQueueRevision','401','-ExpectedWorkItemVersion','30','-Status','in_progress','-DryRun')) $false
    $emergencyQueue.workItems=@($emergencyQueue.workItems|Where-Object{$_.id-ne'wi-test-emergency-active'});Write-Utf8Json $emergencyQueuePath $emergencyQueue
    Add-ExitCheck 'wip:allow-first-emergency' (Invoke-Script (Join-Path $PSScriptRoot 'Update-MarketingQueue.ps1') @('-QueuePath',$emergencyQueuePath,'-ControlPath',$emergencyControl,'-RegistryPath',$registryPath,'-WorkItemId',$target.id,'-ExpectedQueueRevision','401','-ExpectedWorkItemVersion','30','-Status','in_progress','-DryRun'))

    $newArgs=@('-Client','NKCDC','-DedupeKey','fixture:nkcdc:test-only','-Title','Fixture capture','-RequestedOutcome','Prove exact routing and stale-safe capture.','-SourceType','user','-SourceLocator','fixture://local','-SourceSummary','Synthetic redacted test observation.','-Priority','P3','-PriorityRationale','Test only.','-NextAction','Validate without committing.','-ActionClass','local_test','-DefinitionOfDone','Dry run returns a routed work item.','-ExpectedQueueRevision',[string]$queue.revision,'-DryRun')
    Add-ExitCheck 'queue:new-work-dry-run' (Invoke-Script (Join-Path $PSScriptRoot 'New-MarketingWorkItem.ps1') $newArgs)
    $dedupeArgs=@('-Client','NKCDC','-DedupeKey',('  '+[string]$nkcdc.dedupeKey.ToUpperInvariant()+'  '),'-Title','Duplicate fixture','-RequestedOutcome','Reject normalized duplicate state.','-SourceType','user','-SourceLocator','fixture://local','-SourceSummary','Synthetic redacted test observation.','-Priority','P3','-PriorityRationale','Test only.','-NextAction','Validate without committing.','-ActionClass','local_test','-DefinitionOfDone','Duplicate is rejected.','-ExpectedQueueRevision',[string]$queue.revision,'-DryRun')
    Add-ExitCheck 'queue:reject-normalized-dedupe' (Invoke-Script (Join-Path $PSScriptRoot 'New-MarketingWorkItem.ps1') $dedupeArgs) $false

    # System-state evidence refresh is stale-safe, atomic, version-preserving, and audited.
    $systemQueue=Copy-JsonObject $queue;$systemQueue.revision=601;$systemQueue.updatedAt='2026-07-16T12:45:00Z';$systemFixtureItem=@($systemQueue.systemBacklog|Where-Object{$_.id-eq'sys-20260716-0004'})[0];$systemFixtureItem.status='blocked';$systemFixtureItem.risk='Synthetic blocked access state for transaction testing.';$systemFixtureItem|Add-Member -NotePropertyName nextAction -NotePropertyValue 'Run the isolated system-state transaction fixture.' -Force;if($null-ne$systemFixtureItem.PSObject.Properties['result']){$systemFixtureItem.PSObject.Properties.Remove('result')}
    $systemRoot=Join-Path $tempRoot 'system-state';$systemQueuePath=Join-Path $systemRoot 'queue.json';$systemControlPath=Join-Path $systemRoot 'CONTROL.md';$systemBackupRoot=Join-Path $systemRoot 'backups';$systemMutationLog=Join-Path $systemRoot 'queue-mutations.jsonl';$systemHealthPath=Join-Path $projectRoot 'state\system-health.json';Write-Utf8Json $systemQueuePath $systemQueue
    Add-ExitCheck 'system-state:initial-control-render' (Invoke-Script (Join-Path $PSScriptRoot 'Update-MarketingControl.ps1') @('-QueuePath',$systemQueuePath,'-OutputPath',$systemControlPath,'-HealthPath',$systemHealthPath,'-AsOf',[string]$systemQueue.updatedAt,'-InternalRender'))
    $systemRisk='Secure bootstrap is present and the open vault identity still requires confirmation before exact item mapping.'
    $systemNextAction='Confirm the primary vault identity, then map exact bw://item/<guid> locators without reading secret values.'
    $systemVaultState='primary-bitwarden-secure-bootstrap-present-chrome-extension-open-identity-unverified-exact-guid-mapping-pending'
    $systemBridgeState='v1.1.2-locked-bootstrap-present-no-secret-output'
    $systemArgs=@('-SystemBacklogId','sys-20260716-0004','-ExpectedQueueRevision','601','-Risk',$systemRisk,'-NextAction',$systemNextAction,'-CredentialVaultState',$systemVaultState,'-CredentialBridgeState',$systemBridgeState,'-QueuePath',$systemQueuePath,'-ControlPath',$systemControlPath,'-HealthPath',$systemHealthPath,'-BackupRoot',$systemBackupRoot,'-MutationLogPath',$systemMutationLog)
    $queueHashBefore=(Get-FileHash -LiteralPath $systemQueuePath -Algorithm SHA256).Hash;$controlHashBefore=(Get-FileHash -LiteralPath $systemControlPath -Algorithm SHA256).Hash
    $systemDryRun=Invoke-Script (Join-Path $PSScriptRoot 'Update-MarketingSystemState.ps1') ($systemArgs+@('-DryRun'));Add-ExitCheck 'system-state:dry-run' $systemDryRun;$systemDryRunJson=Read-JsonOutput $systemDryRun
    Add-Check 'system-state:dry-run-contract' ($systemDryRunJson.status-eq'would-update'-and[int]$systemDryRunJson.priorQueueRevision-eq601-and[int]$systemDryRunJson.queueRevision-eq602-and[bool]$systemDryRunJson.clientWorkItemVersionsPreserved) ([string]$systemDryRun.output)
    $queueHashAfter=(Get-FileHash -LiteralPath $systemQueuePath -Algorithm SHA256).Hash;$controlHashAfter=(Get-FileHash -LiteralPath $systemControlPath -Algorithm SHA256).Hash
    Add-Check 'system-state:dry-run-no-write' ($queueHashBefore-ceq$queueHashAfter-and$controlHashBefore-ceq$controlHashAfter-and-not(Test-Path -LiteralPath $systemMutationLog)-and-not(Test-Path -LiteralPath $systemBackupRoot)) 'queue-control-log-backup-unchanged'
    $staleSystemArgs=@($systemArgs);$staleSystemArgs[[array]::IndexOf($staleSystemArgs,'-ExpectedQueueRevision')+1]='600';Add-ExitCheck 'system-state:reject-stale-revision' (Invoke-Script (Join-Path $PSScriptRoot 'Update-MarketingSystemState.ps1') ($staleSystemArgs+@('-DryRun'))) $false
    $missingSystemArgs=@($systemArgs);$missingSystemArgs[[array]::IndexOf($missingSystemArgs,'-SystemBacklogId')+1]='sys-missing-item';Add-ExitCheck 'system-state:reject-missing-id' (Invoke-Script (Join-Path $PSScriptRoot 'Update-MarketingSystemState.ps1') ($missingSystemArgs+@('-DryRun'))) $false
    $unsafeSystemArgs=@($systemArgs);$unsafeSystemArgs[[array]::IndexOf($unsafeSystemArgs,'-Risk')+1]='password: REDACTED';Add-ExitCheck 'system-state:reject-unsafe-text' (Invoke-Script (Join-Path $PSScriptRoot 'Update-MarketingSystemState.ps1') ($unsafeSystemArgs+@('-DryRun'))) $false
    $duplicateSystemQueue=Copy-JsonObject $systemQueue;$duplicateSystemQueue.systemBacklog=@($duplicateSystemQueue.systemBacklog)+(Copy-JsonObject (@($duplicateSystemQueue.systemBacklog|Where-Object{$_.id-eq'sys-20260716-0004'})[0]));$duplicateSystemQueuePath=Join-Path $systemRoot 'duplicate-queue.json';Write-Utf8Json $duplicateSystemQueuePath $duplicateSystemQueue
    $duplicateSystemArgs=@($systemArgs);$duplicateSystemArgs[[array]::IndexOf($duplicateSystemArgs,'-QueuePath')+1]=$duplicateSystemQueuePath;Add-ExitCheck 'system-state:reject-duplicate-id' (Invoke-Script (Join-Path $PSScriptRoot 'Update-MarketingSystemState.ps1') ($duplicateSystemArgs+@('-DryRun'))) $false

    $clientVersionsBefore=@($systemQueue.workItems|ForEach-Object{'{0}:{1}'-f$_.id,[int]$_.version})-join'|'
    $systemUpdate=Invoke-Script (Join-Path $PSScriptRoot 'Update-MarketingSystemState.ps1') $systemArgs;Add-ExitCheck 'system-state:isolated-update' $systemUpdate;$systemUpdateJson=Read-JsonOutput $systemUpdate;$updatedSystemQueue=Get-Content -LiteralPath $systemQueuePath -Raw -Encoding UTF8|ConvertFrom-Json;$updatedSystemItem=@($updatedSystemQueue.systemBacklog|Where-Object{$_.id-eq'sys-20260716-0004'})[0];$clientVersionsAfter=@($updatedSystemQueue.workItems|ForEach-Object{'{0}:{1}'-f$_.id,[int]$_.version})-join'|'
    Add-Check 'system-state:root-only-version-increment' ([int]$updatedSystemQueue.revision-eq602-and$clientVersionsBefore-ceq$clientVersionsAfter-and[bool]$systemUpdateJson.clientWorkItemVersionsPreserved) ("revision={0};versions={1}"-f$updatedSystemQueue.revision,$clientVersionsAfter)
    Add-Check 'system-state:truthful-blocked-refresh' ($updatedSystemItem.status-eq'blocked'-and$updatedSystemItem.risk-eq$systemRisk-and$updatedSystemItem.nextAction-eq$systemNextAction-and$updatedSystemQueue.systemHealth.credentialVault-eq$systemVaultState-and$updatedSystemQueue.systemHealth.credentialBridge-eq$systemBridgeState) ([string]$updatedSystemItem.status)
    Add-ExitCheck 'system-state:paired-control-current' (Invoke-Script (Join-Path $PSScriptRoot 'Update-MarketingControl.ps1') @('-QueuePath',$systemQueuePath,'-OutputPath',$systemControlPath,'-HealthPath',$systemHealthPath,'-Check'))
    $backupPath=[string]$systemUpdateJson.backup;$backupValid=-not[string]::IsNullOrWhiteSpace($backupPath)-and(Test-Path -LiteralPath (Join-Path $backupPath 'work-items.json') -PathType Leaf)-and(Test-Path -LiteralPath (Join-Path $backupPath 'CONTROL.md') -PathType Leaf);Add-Check 'system-state:backup-created' $backupValid $backupPath
    $systemMutation=if(Test-Path -LiteralPath $systemMutationLog){Get-Content -LiteralPath $systemMutationLog -Tail 1|ConvertFrom-Json}else{$null};Add-Check 'system-state:audit-recorded' ($null-ne$systemMutation-and$systemMutation.action-eq'system-state-update'-and$systemMutation.systemBacklogId-eq'sys-20260716-0004'-and$systemMutation.priorSystemBacklogStatus-eq'blocked'-and$systemMutation.systemBacklogStatus-eq'blocked'-and[int]$systemMutation.priorQueueRevision-eq601-and[int]$systemMutation.queueRevision-eq602-and-not[bool]$systemMutation.externalActionTaken) ([string]$systemMutation.action)

    $systemCompletionResult='Authorized client access is operational through exact non-secret routes. Retired-account remediation remains explicitly deferred by the owner.'
    $systemDoneArgs=@('-SystemBacklogId','sys-20260716-0004','-ExpectedQueueRevision','602','-TargetStatus','done','-Result',$systemCompletionResult,'-CredentialVaultState','primary-vault-operational-secondary-remediation-deferred','-CredentialBridgeState',$systemBridgeState,'-QueuePath',$systemQueuePath,'-ControlPath',$systemControlPath,'-HealthPath',$systemHealthPath,'-BackupRoot',$systemBackupRoot,'-MutationLogPath',$systemMutationLog)
    $missingDoneResultArgs=@('-SystemBacklogId','sys-20260716-0004','-ExpectedQueueRevision','602','-TargetStatus','done','-CredentialVaultState','primary-vault-operational-secondary-remediation-deferred','-CredentialBridgeState',$systemBridgeState,'-QueuePath',$systemQueuePath,'-ControlPath',$systemControlPath,'-HealthPath',$systemHealthPath,'-BackupRoot',$systemBackupRoot,'-MutationLogPath',$systemMutationLog,'-DryRun');Add-ExitCheck 'system-state:reject-done-without-result' (Invoke-Script (Join-Path $PSScriptRoot 'Update-MarketingSystemState.ps1') $missingDoneResultArgs) $false
    $unsafeDoneArgs=@($systemDoneArgs);$unsafeDoneArgs[[array]::IndexOf($unsafeDoneArgs,'-Result')+1]='password: REDACTED';Add-ExitCheck 'system-state:reject-unsafe-result' (Invoke-Script (Join-Path $PSScriptRoot 'Update-MarketingSystemState.ps1') ($unsafeDoneArgs+@('-DryRun'))) $false
